export const ZONES=[
 {at:0 ,name:"ZONE I · HULL",  log:"Outer hull. Pressure gone, power on a trickle. Everything here still works the way it was built to."},
 {at:6 ,name:"ZONE II · CARGO",log:"Cargo tiers. Mass moves slower than you do, and the buffer only reaches back so far."},
 {at:12,name:"ZONE III · CORE",log:"Core housing. The plating is spent and the lattice keeps changing its mind about what is solid."},
 {at:18,name:"ZONE IV · VOID", log:"Outer void. No floor, no ceiling, no second chances. Only what you were carrying when you pushed off."},
 {at:24,name:"ZONE V · RELAY", log:"The relay still has power. Belts turning, projectors warm, something at the far end still listening. This is the way out."}];
export const zoneOf=i=>{let z=ZONES[0];for(const x of ZONES) if(i>=x.at) z=x; return z;};

